export const source = "'use client';\n\nimport { CartesianGrid, Line, LineChart, XAxis } from 'recharts';\n\nimport {\n  type ChartConfig,\n  ChartContainer,\n  ChartLegend,\n  ChartLegendContent,\n  ChartTooltip,\n  ChartTooltipContent,\n} from '@/components/chart/chart';\n\nconst data = [\n  { month: 'January', desktop: 186, mobile: 80 },\n  { month: 'February', desktop: 305, mobile: 200 },\n  { month: 'March', desktop: 237, mobile: 120 },\n  { month: 'April', desktop: 173, mobile: 190 },\n  { month: 'May', desktop: 209, mobile: 130 },\n  { month: 'June', desktop: 264, mobile: 140 },\n];\n\nconst config = {\n  desktop: {\n    label: 'Desktop',\n    color: 'var(--nx-color-chart-categorical-1)',\n  },\n  mobile: {\n    label: 'Mobile',\n    color: 'var(--nx-color-chart-categorical-2)',\n  },\n} satisfies ChartConfig;\n\nconst shortMonth = (value: string) => value.slice(0, 3);\n\nexport default function ChartLine() {\n  return (\n    <ChartContainer config={config} className=\"nx:w-full nx:max-w-md\">\n      <LineChart data={data} margin={{ left: 12, right: 12 }}>\n        <CartesianGrid vertical={false} />\n        <XAxis\n          dataKey=\"month\"\n          tickLine={false}\n          axisLine={false}\n          tickMargin={8}\n          tickFormatter={shortMonth}\n        />\n        <ChartTooltip content={<ChartTooltipContent indicator=\"line\" />} />\n        <ChartLegend content={<ChartLegendContent />} />\n        <Line\n          dataKey=\"desktop\"\n          type=\"natural\"\n          stroke=\"var(--color-desktop)\"\n          strokeWidth={2}\n          dot={false}\n        />\n        <Line\n          dataKey=\"mobile\"\n          type=\"natural\"\n          stroke=\"var(--color-mobile)\"\n          strokeDasharray=\"6 4\"\n          strokeWidth={2}\n          dot={false}\n        />\n      </LineChart>\n    </ChartContainer>\n  );\n}\n";
